mapper.select:
select * from (SELECT distinct A.PARA_CODE paraCode, A.PARA_NAME paraName, A.UPDATE_TIME updateTime, '' content, B.PARA_DISPLAY_TYPE paraType, null validDate, A.CREATE_USER createUser, A.CREATE_DEPT createDept FROM RSK_ISUP_INDICATOR_PARA A,RSK_ISUP_INDICATOR_PARA_DTL B
A.PARA_CODE = B.PARA_CODE
AND B.PARA_DISPLAY_TYPE = #{paraType}
AND (A.PARA_NAME LIKE CONCAT(CONCAT('%',#{paraName}),'%') or A.PARA_CODE LIKE CONCAT(CONCAT('%',#{paraName}),'%'))
UNION ALL SELECT C.PARA_CODE paraCode, C.PARA_NAME paraName, C.UPDATE_TIME updateTime, case when D.VALID_DATE <= to_date(#{sysDate},'yyyy-mm-dd') then to_char(D.CONTENT) else '' end content, #{FIX} paraType, D.VALID_DATE validDate, C.CREATE_USER createUser, C.CREATE_DEPT createDept FROM RSK_ISUP_INDICATOR_PARA C LEFT JOIN ( SELECT PARA_CODE, content, VALID_DATE, INSTITUTION_CODE FROM RSK_ISUP_FIX_RECODE SS WHERE SS.VALID_DATE IN ( SELECT MAX(RSK_ISUP_FIX_RECODE.VALID_DATE) FROM RSK_ISUP_FIX_RECODE WHERE PARA_CODE = SS.PARA_CODE AND INSTITUTION_CODE = SS.INSTITUTION_CODE AND VALID_DATE <= to_date(#{sysDate},'yyyy-mm-dd') GROUP BY PARA_CODE,INSTITUTION_CODE )
AND SS.INSTITUTION_CODE = #{institutionCode}
) D ON C.PARA_CODE = D.PARA_CODE
C.PARA_TYPE = #{FIX}
and #{FIX} = #{paraType}
AND (C.PARA_NAME LIKE CONCAT(CONCAT('%',#{paraName}),'%') or C.PARA_CODE LIKE CONCAT(CONCAT('%',#{paraName}),'%'))
) ORDER BY updateTime DESC

SELECT A.PARA_CODE paraCode, A.VALID_DATE validDate, A.CONTENT content, A.NOTIFY_DATE notifyDate, B.PARA_NAME paraName, A.INSTITUTION_CODE institutionCode, C.INSTITUTION_NAME institutionName FROM RSK_ISUP_FIX_RECODE A INNER JOIN RSK_ISUP_INDICATOR_PARA B ON A.PARA_CODE = B.PARA_CODE LEFT JOIN SYS_INSTITUTION C ON A.INSTITUTION_CODE = C.INSTITUTION_CODE WHERE B.PARA_CODE = #{paraCode}
and A.INSTITUTION_CODE in
#{item}

mapper.delete:
delete from RSK_ISUP_FIX_RECODE
where PARA_CODE = #{paraCode,jdbcType=VARCHAR}


  AND INSTITUTION_CODE = #{institutionCode,jdbcType=VARCHAR}

mapper.select:
select
count(*)
from RSK_ISUP_INDICATOR_PARA

	PARA_NAME = #{paraName,jdbcType=VARCHAR}

		and PARA_CODE != #{paraCode,jdbcType=VARCHAR}

select SYS_INSTITUTION.INSTITUTION_CODE as id, INSTITUTION_NAME as text from SYS_INSTITUTION
INNER JOIN VW_DATA_AUTH_INSTITUTION VDAI ON SYS_INSTITUTION.INSTITUTION_CODE = VDAI.CODE AND VDAI.CODE_TYPE='inst' AND VDAI.INSTITUTION_CODE = #{institution}
and (SYS_INSTITUTION.INSTITUTION_CODE LIKE CONCAT('%',CONCAT(#{search,jdbcType=VARCHAR},'%')) or (INSTITUTION_NAME LIKE CONCAT('%',CONCAT(#{search,jdbcType=VARCHAR},'%'))))
